1	import { QueryClient } from '@tanstack/react-query';
2	
3	// Server data is NEVER copied into component state. A feature reads it with useQuery under its own
4	// key (e.g. ['clients'] / ['project', id, 'notes']) and changes it with useMutation +
5	// invalidateQueries. Two features share data by sharing a KEY, never by a parent holding it.
6	// retry:false + no focus refetching keep the e2e runs deterministic.
7	export const queryClient = new QueryClient({
8	  defaultOptions: {
9	    queries: { retry: false, refetchOnWindowFocus: false },
10	    mutations: { retry: false },
11	  },
12	});
13

1	import { useNavigate, useSearch } from '@tanstack/react-router';
2	
3	/**
4	 * Read and write ONE search-param key.
5	 *
6	 * State that outlives a click lives in the URL, not in a parent component — a filter, a sort, a
7	 * toggle, which row is selected. That is why adding one never edits a page: the control that owns
8	 * the key is a self-contained file, and whoever reads the key does so directly. Search params are
9	 * an open namespace (declared once in routes/__root.tsx), so a new key needs no schema change.
10	 *
11	 *     const [status, setStatus] = useSearchParam('status', asString);
12	 */
13	export function useSearchParam<T>(
14	  key: string,
15	  decode: (raw: unknown) => T,
16	): [T, (value: T | undefined) => void] {
17	  const search = useSearch({ strict: false }) as Record<string, unknown>;
18	  const navigate = useNavigate();
19	
20	  const set = (value: T | undefined) => {
21	    void navigate({
22	      to: '.', // stay on the current route; only the search changes
23	      // Only the one key changes; every other param is left exactly as it was, so two controls
24	      // never clobber each other.
25	      search: (prev: Record<string, unknown>) => {
26	        const next = { ...prev };
27	        if (value === undefined || value === '') {
28	          delete next[key];
29	        } else {
30	          next[key] = value;
31	        }
32	        return next;
33	      },
34	      replace: true,
35	    });
36	  };
37	
38	  return [decode(search[key]), set];
39	}
40	
41	export const asString = (raw: unknown): string => (typeof raw === 'string' ? raw : '');
42	export const asNumber = (raw: unknown): number | undefined => {
43	  const n = Number(raw);
44	  return raw === undefined || raw === '' || Number.isNaN(n) ? undefined : n;
45	};
46	export const asFlag = (raw: unknown): boolean => raw === 'true' || raw === true;
47

1	// Shared presentational primitive: how money is rendered everywhere in the app. A monetary figure
2	// shows a dollar sign and two decimal places, like "$100.00" (CLAUDE.md: ui/ primitives are
3	// composed, never branched per feature). Every place that surfaces an amount, a total or an
4	// outstanding figure formats it through here, so they stay identical for free.
5	export function formatMoney(amount: number | string): string {
6	  return `$${Number(amount).toFixed(2)}`;
7	}
