1	import React from 'react';
2	import { createRoot } from 'react-dom/client';
3	import { RouterProvider, createRouter } from '@tanstack/react-router';
4	import { QueryClientProvider } from '@tanstack/react-query';
5	import { routeTree } from './routeTree.gen';
6	// Side-effect import: finds every features/**/*.slot.tsx and registers it. Must run before render.
7	import './slots/discover';
8	import { queryClient } from './query/queryClient';
9	
10	// The app's only wiring, written once: the router (its tree is generated from routes/) and the
11	// query cache (its keys are an open namespace). Nothing here needs to change when a feature is
12	// added — a new feature is a new file under routes/ or features/. Do not edit this file.
13	const router = createRouter({ routeTree, context: { queryClient } });
14	
15	declare module '@tanstack/react-router' {
16	  interface Register {
17	    router: typeof router;
18	  }
19	}
20	
21	createRoot(document.getElementById('root')!).render(
22	  <React.StrictMode>
23	    <QueryClientProvider client={queryClient}>
24	      <RouterProvider router={router} />
25	    </QueryClientProvider>
26	  </React.StrictMode>,
27	);
