3	import java.util.regex.Pattern;
4	import net.officefloor.server.http.HttpException;
5	import net.officefloor.server.http.HttpStatus;
6	import net.officefloor.web.ObjectResponse;
7	import org.springframework.web.bind.annotation.RequestBody;
8	
9	/**
10	 * POST /api/clients — create a client from {name, email} and return the saved row (with its id).
11	 * Wired by {@code officefloor/rest/api/clients.POST.yml}.
12	 *
13	 * <p>Every client must have a proper email address: an empty or malformed address is rejected with
14	 * 400 so the row is never persisted (the front-end enforces the same rule, and the DB carries a
15	 * CHECK constraint as the last line of defence).
16	 */
17	public class ClientsPost {
18	
19	    // Mirror of the front-end EMAIL_PATTERN: one @, non-empty local/domain parts, dotted domain.
20	    private static final Pattern EMAIL = Pattern.compile("^[^\\s@]+@[^\\s@]+\\.[^\\s@]+$");
21	
22	    public void service(@RequestBody NewClient body, ClientRepository clients,
23	            ObjectResponse<Client> response) {
24	        String email = body.getEmail();
25	        if (email == null || !EMAIL.matcher(email.trim()).matches()) {
26	            throw new HttpException(HttpStatus.BAD_REQUEST);
27	        }
28	        Client client = new Client();
29	        client.setName(body.getName());
30	        client.setEmail(email.trim());
31	        response.send(clients.save(client));
32	    }
33	}
